-- Adds auction house name from RIXO PRICE SHEET.csv and replaces all rixo_mapping rows (173).
-- Regenerated by scripts/regenerate_rixo_mapping_sql.py
--
-- Idempotent ADD COLUMN: if a previous run failed after ALTER, a plain ALTER would error
-- and keep Flyway stuck in "failed migration" state (backend never starts → nginx 502).

SET @col_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE()
    AND TABLE_NAME = 'rixo_mapping'
    AND COLUMN_NAME = 'auction_name'
);
SET @ddl := IF(
  @col_exists = 0,
  'ALTER TABLE rixo_mapping ADD COLUMN auction_name VARCHAR(255) NULL AFTER rixo_company',
  'SELECT 1'
);
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

DELETE FROM rixo_mapping;

